window.SK_FONT="data:font/woff2;base64,";
window.SK_CSS="/* Sumi Koi: the room behind, the ink-on-paper bar, the scroll intro, the cards and the celebrations.\n * No CSS gradients, shadows or glows: every frame, button and title is painted art (front/assets). */\n@font-face{font-family:\"Shippori Mincho B1\";src:url(fonts/shippori.woff2) format(\"woff2\");font-weight:700;font-display:block}\n:root{\n  --ink:#1b1a18; --paper:#f2ead8; --red:#c8372d; --indigo:#2d4a7a; --gold:#c9a24a; --wood:#140e0a;\n  --lz-bg:#140e0a; --lz-panel:transparent; --lz-panel-solid:#f2ead8; --lz-line:rgba(27,26,24,.25);\n  --lz-text:#1b1a18; --lz-muted:#6d655a; --lz-accent:#c8372d; --lz-accent-ink:#f2ead8; --lz-accent2:#c8372d;\n  --lz-font-display:\"Shippori Mincho B1\",serif; --lz-font-body:\"Shippori Mincho B1\",serif;\n  --lz-action-bg:none; --lz-shadow:0 0 0 transparent; --lz-radius:4px;\n}\nbody{background:var(--wood);color:var(--ink)}\n.skd{display:inline-block;height:1em;background-repeat:no-repeat;vertical-align:-.08em;margin-right:-.04em}\n.skc{display:inline-block;font:700 .62em/1 var(--lz-font-display);vertical-align:.18em;margin:0 .06em;color:inherit}\n\n/* ---------- the room ---------- */\n.sk-bg{position:fixed;inset:0;z-index:0;overflow:hidden;background:var(--wood);pointer-events:none}\n.sk-bg i{position:absolute;inset:-3%;background-position:center;background-size:cover;background-repeat:no-repeat}\n.sk-room{background-image:url(assets/bg/room-wide.webp);animation:skDrift 24s ease-in-out infinite alternate,skCandle 5.3s ease-in-out infinite}\n.sk-night{background-image:url(assets/bg/night-wide.webp);opacity:0;transition:opacity 1.4s ease;animation:skDrift 24s ease-in-out infinite alternate}\n.sk-bg.night .sk-night{opacity:1}\n.sk-bg i.sk-bamboo{inset:auto;left:67%;top:14%;width:24%;height:58%;background:url(assets/bg/bamboo.webp) center bottom/contain no-repeat;opacity:.32;mix-blend-mode:multiply;transform-origin:50% 100%;animation:skSway 6.5s ease-in-out infinite alternate}\n.sk-bg i.sk-bamboo.b2{display:none}\n.sk-bg.night i.sk-bamboo{opacity:.16}\n@media (max-aspect-ratio:1/1){\n  .sk-room{background-image:url(assets/bg/room-tall.webp)}\n  .sk-night{background-image:url(assets/bg/night-tall.webp)}\n  .sk-bg i.sk-bamboo{left:auto;right:-4%;top:4%;width:30%;height:52%}\n  .sk-bg i.sk-bamboo.b2{display:block;right:auto;left:-6%;transform:scaleX(-1);animation-delay:-3s}\n}\n@keyframes skDrift{from{transform:scale(1) translate(0,0)}to{transform:scale(1.045) translate(-1.2%,.6%)}}\n@keyframes skCandle{0%,100%{filter:brightness(1)}30%{filter:brightness(1.05)}55%{filter:brightness(.96)}80%{filter:brightness(1.03)}}\n@keyframes skSway{from{transform:skewX(-2.5deg) translateX(-1%)}to{transform:skewX(2.5deg) translateX(1%)}}\n\n/* ---------- frame ---------- */\n#lzApp{background:none}\n#lzApp .lz-stage,#lzApp .lz-stage.sk-stage{background:none;border:0;border-radius:0;overflow:hidden;display:block}\n.sk-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n.sk-flat .sk-canvas{display:none}\n\n/* ---------- HUD on the stage ---------- */\n.sk-hud{position:absolute;inset:0;z-index:3;pointer-events:none}\n.sk-boardbox,.sk-koibox{position:absolute;pointer-events:none}\n.sk-drops{position:absolute;display:flex;flex-direction:column;align-items:flex-start;gap:4px;transition:opacity .3s}\n.sk-dropsrow{display:flex;flex-wrap:wrap;max-width:110px;gap:3px}\n.sk-dropsrow img{width:clamp(14px,2.4vh,22px);height:auto;display:block;animation:skIn .25s ease-out}\n.sk-dropsn{font-size:clamp(18px,3vh,30px);color:var(--gold)}\n.sk-drops.empty{opacity:.35}\n.sk-hud[data-wide=\"0\"] .sk-drops{flex-direction:row;align-items:center}\n.sk-hud[data-wide=\"0\"] .sk-dropsrow{max-width:none;flex-wrap:nowrap}\n.sk-hud[data-wide=\"0\"] .sk-dropsrow img{width:clamp(12px,3.4vw,18px)}\n\n.sk-card{position:absolute;left:50%;top:44%;width:min(78%,720px);transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:1vh}\n.sk-card img{width:100%;height:auto;display:block}\n.sk-cardsub{font-size:clamp(28px,7vh,72px);color:var(--gold);line-height:1}\n.sk-card.in img{animation:skSlam .5s cubic-bezier(.2,1.4,.4,1) both}\n.sk-card.in .sk-cardsub{animation:skIn .4s .2s ease-out both}\n.sk-card.out{animation:skOut .3s ease-in both}\n\n.sk-small{position:absolute;left:50%;top:74%;transform:translate(-50%,-50%);font-size:clamp(30px,6vh,58px);color:var(--gold);line-height:1;white-space:nowrap}\n.sk-small.in{animation:skPop .35s cubic-bezier(.2,1.5,.4,1) both}\n.sk-small.out{animation:skOut .22s ease-in both}\n\n/* the named win */\n.sk-big{position:absolute;inset:0;z-index:5;pointer-events:auto;display:grid;place-items:center;overflow:hidden}\n.sk-bigdim{position:absolute;inset:0;background:rgba(242,234,216,.62);opacity:0;transition:opacity .5s ease}\n.sk-big:not(.out) .sk-bigdim{opacity:1}\n.sk-bigflash{position:absolute;inset:0;background:var(--paper);opacity:0;pointer-events:none}\n.sk-big.hit .sk-bigflash{animation:skFlash .45s ease-out both}\n.sk-bigink{position:absolute;left:50%;top:46%;width:0;height:0}\n.sk-sp{position:absolute;left:0;top:0;width:clamp(120px,28vmin,320px);height:auto;translate:-50% -50%;opacity:0;animation:skSplash 1.8s var(--d) cubic-bezier(.15,.9,.3,1) forwards}\n.sk-sp.g{filter:sepia(1) saturate(4) hue-rotate(-12deg) brightness(1.15)}\n.sk-bigin{position:relative;display:flex;flex-direction:column;align-items:center;gap:1.4vh;width:min(88%,820px)}\n.sk-bigtitle{width:100%;height:auto;display:block;opacity:0}\n.sk-bigamt{font-size:clamp(40px,10vh,110px);color:var(--gold);line-height:1;white-space:nowrap;transform:scale(var(--grow,1));opacity:0}\n.sk-big.pre .sk-bigin{animation:skGather .6s ease-in both}\n.sk-big.hit .sk-bigtitle,.sk-big.count .sk-bigtitle,.sk-big.slam .sk-bigtitle{opacity:1}\n.sk-big.hit .sk-bigtitle{animation:skSlam .5s cubic-bezier(.2,1.5,.4,1) both}\n.sk-big.count .sk-bigamt,.sk-big.slam .sk-bigamt,.sk-big.hit .sk-bigamt{opacity:1}\n.sk-big.up .sk-bigtitle{animation:skBump .45s cubic-bezier(.2,1.6,.4,1)}\n.sk-big.slam .sk-bigamt{animation:skPop .45s cubic-bezier(.2,1.7,.4,1)}\n.sk-big.slam .sk-bigin{animation:skShake .35s linear}\n.sk-big.out{animation:skOut .38s ease-in both}\n.sk-big.t3 .sk-bigin{width:min(94%,900px)}\n\n/* ---------- the bar: a strip of paper, ink controls ---------- */\n#lzApp.sk-bar{grid-template-rows:0 minmax(0,1fr) auto!important;row-gap:0!important;padding:0!important}\n#lzApp.sk-bar .lz-top{display:none!important}\n#lzApp.sk-bar [hidden]{display:none!important}\n#lzApp.sk-bar .lz-panel{all:unset;grid-area:panel;position:relative;z-index:10;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:12px;\n  height:clamp(56px,10vh,88px);padding:0 clamp(10px,1.8vw,30px);background:url(assets/ui/paper.webp) center/320px auto repeat;color:var(--ink)}\n#lzApp.sk-bar .lz-panel::before{content:\"\";position:absolute;left:-1%;right:-1%;top:-9px;height:16px;background:url(assets/board/rod.webp) center/100% 100% no-repeat;pointer-events:none}\n#lzApp.sk-bar .lz-panel>.sk-bl{grid-column:1}\n#lzApp.sk-bar .lz-panel>.sk-bc{grid-column:2}\n#lzApp.sk-bar .lz-panel>.sk-br{grid-column:3}\n#lzApp.sk-bar .lz-panel>:not(.sk-bl):not(.sk-bc):not(.sk-br){position:absolute}\n#lzApp.sk-bar .sk-bl{display:flex;align-items:center;gap:14px;min-width:0}\n#lzApp.sk-bar .sk-br{display:flex;align-items:center;justify-content:flex-end;gap:12px;min-width:0}\n#lzApp.sk-bar .sk-icons{display:flex;gap:6px;flex:none}\n#lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto){all:unset;box-sizing:border-box;display:grid;place-items:center;flex:none;cursor:pointer;\n  width:clamp(40px,5.4vh,50px);height:clamp(40px,5.4vh,50px);border-radius:50%;transition:transform .15s ease,background-color .2s}\n#lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto) img{width:62%;height:62%;object-fit:contain;display:block}\n#lzApp.sk-bar #lzSound span{display:grid;place-items:center;width:100%;height:100%}\n#lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto):not(:disabled):hover{transform:scale(1.08);background:rgba(27,26,24,.07)}\n#lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto):active{transform:scale(.94)}\n#lzApp.sk-bar :is(#lzMinus,#lzPlus,#lzFast,#lzAuto):disabled{opacity:.3;cursor:default}\n#lzApp.sk-bar #lzFast[aria-pressed=\"true\"],#lzApp.sk-bar #lzAuto.on{background:rgba(200,55,45,.16)}\n#lzApp.sk-bar .sk-lbl{display:none}\n#lzApp.sk-bar #lzAuto.on .sk-lbl{display:block;position:absolute;top:-14px;font:700 12px/1 var(--lz-font-display);color:var(--red);white-space:nowrap}\n#lzApp.sk-bar #lzAuto{position:relative}\n#lzApp.sk-bar #lzMin,#lzApp.sk-bar #lzMax{display:none!important}\n#lzApp.sk-bar .lz-quick{display:flex!important;align-items:center;gap:6px}\n/* balance and win: a small ink label over the figure */\n#lzApp.sk-bar :is(.lz-wallet,.lz-win){all:unset;display:block;min-width:0}\n#lzApp.sk-bar :is(.lz-wallet,.lz-win) .lz-lbl{display:block;margin:0 0 3px;font:700 16px/1 var(--lz-font-display);letter-spacing:.18em;color:#6d655a}\n#lzApp.sk-bar :is(.lz-wallet,.lz-win) b{display:block;font:700 clamp(18px,2.8vh,28px)/1 var(--lz-font-display);color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n#lzApp.sk-bar .lz-win{text-align:right}\n#lzApp.sk-bar .lz-win.has b{color:var(--red)}\n/* the centre: - enso + */\n#lzApp.sk-bar .lz-field{all:unset;display:block}\n#lzApp.sk-bar .lz-field>.lz-lbl{display:none!important}\n#lzApp.sk-bar .lz-stepper{all:unset;display:flex;align-items:center;gap:4px}\n#lzApp.sk-bar .sk-spinw{position:relative;display:flex;flex:none;margin:0 10px}\n#lzApp.sk-bar #lzAction{all:unset;box-sizing:border-box;--sz:clamp(96px,15vh,128px);position:relative;width:var(--sz);height:var(--sz);margin:calc(var(--sz) * -.42) 0 -6px;display:grid;place-items:center;cursor:pointer;border-radius:50%;transition:transform .18s cubic-bezier(.2,1.5,.4,1)}\n#lzApp.sk-bar #lzAction>img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;transition:opacity .2s,transform .4s}\n#lzApp.sk-bar #lzAction .sk-stop{opacity:0;transform:scale(.6)}\n#lzApp.sk-bar #lzAction.busy .sk-enso{opacity:0;transform:rotate(90deg) scale(.7)}\n#lzApp.sk-bar #lzAction.busy .sk-stop{opacity:1;transform:scale(.62)}\n#lzApp.sk-bar #lzAction.hurry .sk-stop{transform:scale(.5)}\n#lzApp.sk-bar #lzAction:not(:disabled):hover .sk-enso{transform:rotate(-12deg) scale(1.04)}\n#lzApp.sk-bar #lzAction:active{transform:scale(.95)}\n#lzApp.sk-bar #lzAction span{position:relative;font:700 clamp(17px,2.6vh,24px)/1 var(--lz-font-display);letter-spacing:.14em;color:var(--ink)}\n#lzApp.sk-bar #lzAction.busy span{opacity:0}\n#lzApp.sk-bar #lzAction small{display:none}\n#lzApp.sk-bar #lzAction.auto span{font-size:clamp(13px,1.8vh,16px);letter-spacing:.06em;color:var(--red)}\n#lzApp.sk-bar #lzAction:disabled{cursor:default}\n#lzApp.sk-bar #lzAction:disabled:not(.busy){opacity:.55}\n#lzApp.sk-bar .sk-spinw .lz-amount{all:unset;position:absolute;left:50%;bottom:-4px;transform:translateX(-50%);z-index:3;padding:2px 12px;white-space:nowrap;cursor:pointer;\n  background:url(assets/ui/paper.webp) center/200px auto;border:1.5px solid var(--ink);border-radius:3px}\n#lzApp.sk-bar .sk-spinw .lz-amount b{font:700 clamp(16px,2.2vh,20px)/1.2 var(--lz-font-display);color:var(--ink)}\n.sk-amtpop{position:fixed;z-index:60;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:10px;max-width:min(360px,94vw);max-height:60vh;overflow:auto;\n  background:url(assets/ui/paper.webp) center/320px auto;border:2px solid var(--ink);border-radius:4px}\n.sk-amtpop button{all:unset;cursor:pointer;padding:8px 10px;text-align:center;font:700 16px/1.2 var(--lz-font-display);color:var(--ink);border-radius:3px}\n.sk-amtpop button:hover,.sk-amtpop button[aria-selected=\"true\"]{background:rgba(200,55,45,.14);color:var(--red)}\n.sk-hurry{all:unset;position:fixed;z-index:30;cursor:pointer;border-radius:50%}\n\n/* the buy stamp on the stage */\n.sk-buy{position:absolute;z-index:6;margin:0}\n.sk-buy .lz-feat{all:unset;box-sizing:border-box;position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;cursor:pointer;width:clamp(86px,15vh,150px);text-align:center;transition:transform .2s cubic-bezier(.2,1.5,.4,1)}\n.sk-buy .lz-feat .sk-stamp{width:100%;height:auto;display:block;border:3px solid var(--red);border-radius:3px;background:var(--paper)}\n.sk-buy .lz-feat span{font:700 clamp(16px,2.3vh,20px)/1 var(--lz-font-display);color:var(--paper);letter-spacing:.08em;white-space:nowrap}\n.sk-buy .lz-feat small{font:700 16px/1 var(--lz-font-display);color:var(--gold);white-space:nowrap}\n.sk-buy .lz-feat:not(:disabled):hover{transform:translateY(-3px) rotate(-1.5deg)}\n.sk-buy .lz-feat:disabled{opacity:.4;cursor:default}\n.sk-hud[data-wide=\"0\"]~.sk-buy .lz-feat,.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat{width:clamp(64px,18vw,96px);flex-direction:column}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat span{font-size:13px}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat small{font-size:13px}\n\n/* dialogs on paper */\n.lz-modal .lz-sheet{background:url(assets/ui/paper.webp) center/420px auto!important;color:var(--ink)!important;border:2px solid var(--ink)!important;border-radius:4px!important}\n.lz-modal .lz-sheet h2,.lz-modal .lz-sheet h3{font-family:var(--lz-font-display);color:var(--ink)}\n.lz-modal .lz-sheet :is(p,td,th,li){color:var(--ink)}\n.lz-modal .lz-btns button,.lz-modal .lz-seg button,.lz-modal .lz-sheet>button{font-family:var(--lz-font-display)}\n#lzBuy .lz-sheet{max-width:min(460px,94vw)}\n#lzBuy .lz-sheet::before{content:\"\";display:block;width:min(150px,30vh);aspect-ratio:3/4;margin:0 auto 10px;background:url(assets/ui/buy-card.webp) center/cover;border:3px solid var(--red);border-radius:3px}\n#lzBuy .lz-btns{display:flex;justify-content:center;gap:16px;align-items:center}\n#lzBuy #lzBuyNo{all:unset;cursor:pointer;padding:10px 18px;font:700 17px/1 var(--lz-font-display);color:var(--ink);border-bottom:2px solid var(--ink)}\n#lzBuy #lzBuyYes{all:unset;cursor:pointer;width:96px;height:96px;display:grid;place-items:center;font:700 18px/1 var(--lz-font-display);letter-spacing:.1em;color:var(--ink);\n  background:url(assets/enso/red.webp) center/contain no-repeat}\n#lzBuy #lzBuyYes:hover{transform:rotate(-6deg) scale(1.05)}\n\n/* ---------- intro: a scroll unrolls ---------- */\n.lz-intro.sk-intro{background:var(--wood) url(assets/bg/room-wide.webp) center/cover no-repeat;padding:8px}\n@media (max-aspect-ratio:1/1){ .lz-intro.sk-intro{background-image:url(assets/bg/room-tall.webp)} }\n.sk-intro .lz-intro-in{width:min(560px,96vw);gap:0}\n.sk-intro .lz-studio{color:var(--paper);opacity:.6}\n.sk-scroll{display:flex;flex-direction:column;align-items:center;width:100%;transition:transform .55s cubic-bezier(.5,0,.2,1)}\n.sk-rod{width:108%;height:auto;display:block;position:relative;z-index:2}\n.sk-rod.top{margin-bottom:-6px}\n.sk-rod.bot{margin-top:-6px;animation:skRodDown 1.3s .15s cubic-bezier(.3,.8,.3,1) both}\n.sk-sheet{width:100%;display:flex;flex-direction:column;align-items:center;gap:clamp(6px,1.6vh,14px);padding:clamp(10px,2.4vh,24px) clamp(14px,4%,34px) clamp(12px,2.6vh,26px);\n  background:url(assets/ui/paper.webp) center/360px auto;overflow:hidden;animation:skUnroll 1.3s .15s cubic-bezier(.3,.8,.3,1) both;color:var(--ink);text-align:center}\n.sk-intro .lz-intro-logo{height:auto;display:block;animation:skIn .7s .8s ease-out both}\n.sk-intro .lz-intro-logo img{height:clamp(60px,19vh,170px);width:auto;max-width:100%;display:block;margin:0 auto}\n.sk-intro .lz-intro-tag{color:#5c5348;font:700 clamp(12px,2.2vh,17px)/1.3 var(--lz-font-display);margin:0;animation:skIn .6s 1s ease-out both}\n.sk-notes{list-style:none;margin:0;padding:0;display:grid;gap:clamp(4px,1.2vh,12px);width:100%;text-align:left}\n.sk-notes li{display:grid;grid-template-columns:clamp(30px,6vh,52px) minmax(0,1fr);gap:12px;align-items:center;animation:skIn .5s calc(1.15s + var(--i) * .15s) ease-out both}\n.sk-notes img{width:100%;height:auto;display:block}\n.sk-notes b{display:block;font:700 clamp(13px,2.2vh,18px)/1.1 var(--lz-font-display);letter-spacing:.12em;color:var(--red)}\n.sk-notes span{display:block;font:700 clamp(12px,2.1vh,16px)/1.3 var(--lz-font-display);color:var(--ink)}\n.sk-playrow{display:flex;justify-content:center;animation:skIn .5s 1.5s ease-out both}\n.sk-intro .lz-intro-play{all:unset;box-sizing:border-box;position:relative;width:clamp(84px,17vh,130px);height:clamp(84px,17vh,130px);display:grid;place-items:center;cursor:pointer;\n  font:700 clamp(16px,3vh,24px)/1 var(--lz-font-display);letter-spacing:.14em;color:var(--ink);transition:transform .25s cubic-bezier(.2,1.5,.4,1)}\n.sk-intro .lz-intro-play img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;animation:skTurn 14s linear infinite}\n.sk-intro .lz-intro-play:not(:disabled):hover{transform:scale(1.06)}\n.sk-intro .lz-intro-play:disabled{opacity:.6;cursor:default}\n.sk-keep{all:unset;cursor:pointer;display:flex;align-items:center;gap:8px;font:700 clamp(12px,1.9vh,16px)/1 var(--lz-font-display);color:#5c5348}\n.sk-keep i{width:16px;height:16px;border:2px solid var(--ink);border-radius:2px;display:grid;place-items:center}\n.sk-keep[aria-pressed=\"true\"] i{background:var(--red);border-color:var(--red)}\n.sk-intro .lz-intro-load{width:min(240px,70%);height:3px;background:rgba(27,26,24,.15);border-radius:0}\n.sk-intro .lz-intro-load i{background:var(--ink)}\n.sk-intro .lz-intro-fine{color:#5c5348;font:700 12px/1 var(--lz-font-display)}\n.sk-intro.short .sk-notes,.sk-intro.short .lz-intro-tag{display:none}\n@media (max-height:520px){ .sk-notes span{display:none} .sk-notes b{font-size:13px} .sk-intro .lz-intro-logo{height:clamp(48px,16vh,110px)} }\n@media (max-height:330px){ .sk-notes,.sk-intro .lz-intro-tag,.sk-intro .lz-intro-fine,.sk-keep{display:none} .sk-sheet{padding:6px 12px;gap:4px} .sk-intro .lz-intro-logo{height:72px} .sk-intro .lz-intro-play{width:76px;height:76px;font-size:14px} }\n/* the intro never scrolls, in any direction: the scroll shrinks to fit (game.js). A scrolling intro let the phone drag\n   it left and right, because the rods are wider than the sheet (Lidor, iPhone, 2026-11-28) */\n.lz-intro.sk-intro{overflow:hidden;overscroll-behavior:none;touch-action:none}\n\n/* ---------- phone and small frames ---------- */\n/* phone: two rows. Top: turbo, -, the enso, +, auto. Under them: balance left, win right. Info and sound on the stage. */\n@media (max-aspect-ratio:1/1){\n  #lzApp.sk-bar .lz-panel{height:auto;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);grid-template-rows:auto auto;row-gap:0;padding:4px 10px 6px;column-gap:6px}\n  #lzApp.sk-bar .sk-bl,#lzApp.sk-bar .sk-br,#lzApp.sk-bar .lz-quick{display:contents!important}\n  #lzApp.sk-bar .lz-panel>.sk-bc{grid-row:1;grid-column:2}\n  #lzApp.sk-bar #lzFast{grid-row:1;grid-column:1;justify-self:end}\n  #lzApp.sk-bar #lzAuto{grid-row:1;grid-column:3;justify-self:start}\n  #lzApp.sk-bar .lz-wallet{grid-row:2;grid-column:1;justify-self:start;display:flex!important;align-items:baseline;gap:6px}\n  #lzApp.sk-bar .lz-win{grid-row:2;grid-column:3;justify-self:end;display:flex!important;align-items:baseline;gap:6px}\n  #lzApp.sk-bar .lz-panel>.sk-bc{grid-row:1/3}\n  #lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto){width:44px;height:44px}\n  #lzApp.sk-bar #lzAction{--sz:96px;margin:-30px 0 4px}\n  #lzApp.sk-bar #lzAction span{font-size:17px;letter-spacing:.06em}\n  #lzApp.sk-bar .sk-spinw{margin:0 2px}\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) .lz-lbl{font-size:12px;letter-spacing:.1em;margin:0}\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) b{font-size:15px}\n  #lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){visibility:hidden}\n  .sk-icons.on-stage{position:absolute;z-index:7;left:4px;top:4px;display:flex;gap:2px}\n  .sk-icons.on-stage :is(.lz-icon){all:unset;box-sizing:border-box;display:grid;place-items:center;width:44px;height:44px;cursor:pointer;border-radius:50%;background:rgba(242,234,216,.88)}\n  .sk-icons.on-stage img{width:60%;height:60%;object-fit:contain;display:block}\n  .sk-icons.on-stage #lzSound span{display:grid;place-items:center;width:100%;height:100%}\n}\n@media (max-height:330px){\n  #lzApp.sk-bar .lz-panel{height:44px;gap:6px;padding:0 8px}\n  #lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto){width:28px;height:28px}\n  #lzApp.sk-bar #lzAction{--sz:60px;margin:-18px 0 -4px}\n  #lzApp.sk-bar #lzAction span{font-size:12px}\n  #lzApp.sk-bar .sk-spinw .lz-amount{padding:0 6px;bottom:-3px}\n  #lzApp.sk-bar .sk-spinw .lz-amount b{font-size:12px}\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) .lz-lbl{font-size:12px;margin-bottom:1px}\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) b{font-size:12px}\n  #lzApp.sk-bar .sk-icons,#lzApp.sk-bar .lz-quick{flex-direction:row;gap:2px}\n  .sk-buy .lz-feat{width:56px!important}\n  .sk-buy .lz-feat span,.sk-buy .lz-feat small{font-size:12px!important}\n}\n/* while playing: - and + fade, the buy fades */\n#lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){opacity:.25;pointer-events:none}\n.sk-stage:has(~ .lz-panel #lzAction.busy) .sk-buy,#lzApp:has(#lzAction.busy) .sk-buy{opacity:.3;pointer-events:none}\n\n/* ---------- motion ---------- */\n@keyframes skIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n@keyframes skOut{to{opacity:0;transform:scale(.96)}}\n@keyframes skPop{0%{transform:scale(.5)}45%{transform:scale(1.1)}100%{transform:scale(1)}}\n@keyframes skSlam{0%{opacity:0;transform:scale(2.2) rotate(-4deg)}60%{opacity:1;transform:scale(.94) rotate(1deg)}100%{opacity:1;transform:scale(1)}}\n@keyframes skBump{0%{transform:scale(1)}40%{transform:scale(1.12) rotate(-1.5deg)}100%{transform:scale(1)}}\n@keyframes skGather{from{transform:scale(1.3);opacity:0}to{transform:scale(.9);opacity:0}}\n@keyframes skFlash{0%{opacity:.85}100%{opacity:0}}\n@keyframes skShake{0%,100%{translate:0 0}20%{translate:-6px 3px}40%{translate:5px -4px}60%{translate:-4px -2px}80%{translate:3px 4px}}\n@keyframes skSplash{0%{opacity:0;transform:translate(0,0) rotate(var(--r)) scale(.2)}15%{opacity:.95}70%{opacity:.85}100%{opacity:0;transform:translate(var(--x),var(--y)) rotate(var(--r)) scale(var(--s))}}\n@keyframes skUnroll{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0 0 0 0)}}\n@keyframes skRodDown{from{transform:translateY(-12px)}to{transform:none}}\n@keyframes skTurn{to{transform:rotate(360deg)}}\n@media (prefers-reduced-motion:reduce){\n  .sk-room,.sk-night,.sk-bg i.sk-bamboo,.sk-intro .lz-intro-play img{animation:none}\n  .sk-sp{display:none}\n}\n.sk-hud[data-wide=\"0\"] .sk-drops{transform:translate(-50%,-100%)}\n/* phone: info and sound on the stage, on a paper disc */\n#lzApp.sk-bar .sk-icons.on-stage :is(.lz-icon){background:rgba(242,234,216,.9);width:44px;height:44px}\n/* popout S and other very low frames: values only, small stamp, short intro */\n@media (max-height:330px){\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) .lz-lbl{display:none!important}\n  #lzApp.sk-bar :is(.lz-wallet,.lz-win) b{font-size:12px!important}\n  #lzApp.sk-bar .sk-bl,#lzApp.sk-bar .sk-br{gap:4px}\n  #lzApp.sk-bar .lz-panel{column-gap:4px}\n  .sk-buy .lz-feat{width:48px!important;gap:2px}\n  .sk-buy .lz-feat .sk-stamp{border-width:2px}\n  .sk-dropsrow{max-width:72px}\n  .sk-dropsrow img{width:9px!important}\n  .sk-dropsn{font-size:14px}\n  .sk-intro .lz-intro-logo img{height:52px}\n  .sk-intro .lz-intro-play{width:62px;height:62px;font-size:12px}\n  .sk-intro .lz-intro-load{display:none}\n\n  .sk-rod{width:100%}\n  .sk-intro .lz-intro-in{width:min(320px,90vw)}\n}\n/* the centre column: the enso over the play amount, nothing overlapping, nothing past the frame */\n#lzApp.sk-bar .sk-spinw{flex-direction:column;align-items:center;align-self:flex-end}\n#lzApp.sk-bar #lzAction{margin:calc(var(--sz) * -.5) 0 0}\n#lzApp.sk-bar .sk-spinw .lz-amount{position:static;transform:none;margin:2px 0 4px}\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar #lzAction{margin:-34px 0 0} #lzApp.sk-bar .sk-spinw .lz-amount{cursor:default;margin:1px 0 0} }\n@media (max-height:330px){ #lzApp.sk-bar #lzAction{margin:-22px 0 0} #lzApp.sk-bar .sk-spinw .lz-amount{margin:1px 0 2px} }\n/* the menu: rules and sound on a slip of paper */\n.sk-menupop{position:fixed;z-index:60;display:flex;flex-direction:column;gap:2px;padding:8px;background:url(assets/ui/paper.webp) center/320px auto;border:2px solid var(--ink);border-radius:4px}\n.sk-menupop :is(#lzInfo,#lzSound){all:unset;box-sizing:border-box;display:flex;align-items:center;gap:10px;min-height:44px;padding:4px 12px 4px 6px;cursor:pointer;border-radius:3px}\n.sk-menupop :is(#lzInfo,#lzSound):hover{background:rgba(200,55,45,.12)}\n.sk-menupop :is(#lzInfo,#lzSound) img{width:30px;height:30px;object-fit:contain;display:block}\n.sk-menupop #lzSound>span:not(.sk-mlbl){display:grid}\n.sk-menupop .sk-lbl{display:none}\n.sk-menupop .sk-mlbl{font:700 17px/1 var(--lz-font-display);color:var(--ink);letter-spacing:.06em}\n#lzApp.sk-bar .lz-win,#lzApp.sk-bar .lz-wallet{flex:none}\n@media (max-height:330px){ .sk-buy .lz-feat span{display:none} .sk-buy .lz-feat small{font-size:12px!important;color:var(--paper)} }\n/* bar heights (catalog item 1: up to 12% of a phone, 20% of the popout): the panel sizes to its centre column */\n@media (max-aspect-ratio:1/1){\n  #lzApp.sk-bar .lz-panel{padding:2px 10px 4px}\n  #lzApp.sk-bar #lzAction{--sz:96px;margin:-52px 0 0}\n  #lzApp.sk-bar .sk-spinw .lz-amount{min-height:44px;min-width:84px;box-sizing:border-box;display:grid;place-items:center;padding:0 10px;margin:0;cursor:pointer}\n  #lzApp.sk-bar .sk-spinw .lz-amount b{font-size:16px}\n  #lzApp.sk-bar .lz-panel>.sk-bc{align-self:end}\n  #lzApp.sk-bar #lzFast,#lzApp.sk-bar #lzAuto{align-self:start}\n  #lzApp.sk-bar .lz-wallet,#lzApp.sk-bar .lz-win{align-self:end;margin-bottom:6px}\n}\n@media (max-height:330px){\n  #lzApp.sk-bar .lz-panel{height:auto!important;padding:1px 8px}\n  #lzApp.sk-bar #lzAction{--sz:56px;margin:-34px 0 0}\n  #lzApp.sk-bar .sk-spinw .lz-amount{margin:0 0 1px;padding:0 6px}\n  #lzApp.sk-bar .sk-spinw .lz-amount b{font-size:12px;line-height:1.2}\n}\n/* the panel takes the height of its centre column (the stage gives way), never a fixed height that cuts it */\n#lzApp.sk-bar .lz-panel{height:auto;min-height:clamp(52px,9vh,80px);padding-top:2px;padding-bottom:3px}\n#lzApp.sk-bar #lzAction{--sz:clamp(78px,14vh,120px)}\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar #lzAction{--sz:96px;margin:-56px 0 0} #lzApp.sk-bar .lz-panel{min-height:0} }\n@media (max-height:330px){ #lzApp.sk-bar .lz-panel{min-height:0} #lzApp.sk-bar #lzAction{--sz:56px;margin:-38px 0 0} #lzApp.sk-bar .sk-spinw .lz-amount b{line-height:1} }\n@media (max-height:330px){ #lzApp.sk-bar .lz-panel{padding:0 8px} #lzApp.sk-bar #lzAction{margin:-42px 0 0} #lzApp.sk-bar .sk-spinw .lz-amount{margin:0} #lzApp.sk-bar :is(.lz-icon,#lzMinus,#lzPlus,#lzFast,#lzAuto){width:26px;height:26px} }\n/* the buy stamp grows with its label and price (long currencies such as BTC) */\n.sk-buy .lz-feat{width:max-content!important;min-width:0}\n.sk-buy .lz-feat .sk-stamp{width:clamp(86px,15vh,150px)}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat .sk-stamp{width:clamp(56px,15vw,84px)}\n@media (max-height:330px){ .sk-buy .lz-feat .sk-stamp{width:46px} }\n.sk-bigamt{max-width:100%}\n/* replay: no play amount, balance, turbo, auto or buy */\nbody.lz-is-replay #lzApp.sk-bar :is(#lzField,#lzQuick,#lzWallet,#lzFast,#lzAuto,.lz-wallet),body.lz-is-replay .sk-buy{display:none!important}\n.sk-small{max-width:96%}\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar #lzAction{margin:-62px 0 0} #lzApp.sk-bar .lz-panel{padding:0 10px 2px} }\n.sk-small{max-width:none}\n/* ink drops flying from a winning cup to the win counter */\n.sk-fly{position:fixed;z-index:40;width:16px;height:16px;margin:-8px 0 0 -8px;pointer-events:none;animation:skFly .65s var(--d) cubic-bezier(.5,0,.75,.4) both}\n@keyframes skFly{0%{transform:translate(0,0) scale(.6);opacity:0}15%{opacity:1;transform:translate(calc(var(--dx) * .1),-30px) scale(1)}100%{transform:translate(var(--dx),var(--dy)) scale(.5);opacity:.2}}\n#lzApp.sk-bar .lz-win.bump b{animation:skPop .35s cubic-bezier(.2,1.6,.4,1)}\n/* painted numerals: no glyph overhangs its box */\n.sk-bigamt,.sk-cardsub,.sk-smallamt,.sk-dropsn{padding:0 .1em}\n/* the ink switch: CALM (black enso) or WILD (vermilion enso), on the stage by the stamp */\n.sk-ink{position:absolute;z-index:6;display:flex;gap:4px;margin:0;padding:4px;background:rgba(242,234,216,.9);border:2px solid var(--ink);border-radius:4px}\n.sk-ink button{all:unset;box-sizing:border-box;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:58px;min-height:52px;padding:4px 6px;cursor:pointer;border-radius:3px;transition:background-color .2s,transform .2s}\n.sk-ink button img{width:30px;height:30px;object-fit:contain;display:block;transition:transform .4s cubic-bezier(.2,1.5,.4,1)}\n.sk-ink button b{font:700 13px/1 var(--lz-font-display);letter-spacing:.06em;color:var(--ink);white-space:nowrap}\n.sk-ink button[data-mode=\"wild\"] b{color:var(--red)}\n.sk-ink button[aria-pressed=\"true\"]{background:rgba(27,26,24,.1)}\n.sk-ink button[data-mode=\"wild\"][aria-pressed=\"true\"]{background:rgba(200,55,45,.16)}\n.sk-ink button[aria-pressed=\"true\"] img{transform:rotate(-30deg) scale(1.12)}\n.sk-ink button[aria-pressed=\"false\"]{opacity:.62}\n.sk-ink button:not(:disabled):hover{opacity:1}\n.sk-ink button:disabled{cursor:default}\n#lzApp:has(#lzAction.busy) .sk-ink{opacity:.5}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-ink button{min-width:48px;min-height:44px;padding:2px 4px}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-ink button img{width:22px;height:22px}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-ink button b{font-size:12px}\n@media (max-height:330px){ .sk-ink{padding:2px;gap:2px} .sk-ink button{min-width:40px;min-height:30px;padding:1px 3px} .sk-ink button img{width:16px;height:16px} .sk-ink button b{font-size:12px} }\n/* the stamp follows the ink */\n:root:not([data-ink=\"wild\"]) .sk-buy .lz-feat[data-mode=\"wildfever\"],:root[data-ink=\"wild\"] .sk-buy .lz-feat[data-mode=\"fever\"]{display:none!important}\n:root[data-ink=\"wild\"] .sk-buy .lz-feat .sk-stamp{border-color:var(--ink)}\n.sk-ink.stack{flex-direction:column}\n/* the titles are painted on with one brush stroke: ten drawings, each held two ticks of a 24 fps clock */\n.sk-big.hit .sk-bigtitle,.sk-big.up .sk-bigtitle,.sk-card.in img{-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:0 50%;mask-position:0 50%;\n  animation:skSlam .5s cubic-bezier(.2,1.5,.4,1) both,skPaint .42s steps(10,end) both}\n@keyframes skPaint{from{-webkit-mask-size:0% 320%;mask-size:0% 320%}to{-webkit-mask-size:340% 320%;mask-size:340% 320%}}\n.sk-ink button b{font-size:16px}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-ink button b{font-size:13px}\n@media (max-height:330px){ .sk-ink button b{font-size:12px} }\n.sk-bigamt{max-width:76%}.sk-cardsub{max-width:92%}.sk-small .sk-smallamt{max-width:92vw}\n/* the unroll: a sheet of the same paper rolls away downward over the writing. It lets every press through, so PLAY\n   works at any moment of the animation (a clip-path would hide the button from presses while it plays) */\n.sk-sheet{animation:none;position:relative}\n.sk-sheet::after{content:\"\";position:absolute;inset:0;z-index:3;pointer-events:none;background:url(assets/ui/paper.webp) center/360px auto;transform-origin:50% 100%;animation:skCover 1.3s .15s cubic-bezier(.3,.8,.3,1) both}\n@keyframes skCover{from{transform:scaleY(1)}to{transform:scaleY(0)}}\n@media (prefers-reduced-motion:reduce){ .sk-sheet::after{display:none} }\n/* rules and sound on the stage's top left, on paper discs, at every size */\n#lzApp.sk-bar .sk-icons.on-stage{position:absolute;z-index:7;left:10px;top:10px;display:flex;gap:8px}\n#lzApp.sk-bar .sk-icons.on-stage .lz-icon{all:unset;box-sizing:border-box;display:grid;place-items:center;width:clamp(44px,5.6vh,56px);height:clamp(44px,5.6vh,56px);cursor:pointer;border-radius:50%;background:rgba(242,234,216,.92);border:2px solid var(--ink);transition:transform .15s}\n#lzApp.sk-bar .sk-icons.on-stage .lz-icon:hover{transform:scale(1.08)}\n#lzApp.sk-bar .sk-icons.on-stage img{width:58%;height:58%;object-fit:contain;display:block}\n#lzApp.sk-bar .sk-icons.on-stage #lzSound span{display:grid;place-items:center;width:100%;height:100%}\n#lzApp.sk-bar .sk-icons.on-stage .sk-lbl{display:none}\n@media (max-height:330px){ #lzApp.sk-bar .sk-icons.on-stage{left:4px;top:4px;gap:4px} #lzApp.sk-bar .sk-icons.on-stage .lz-icon{width:30px;height:30px;border-width:1.5px} }\n/* while playing nothing vanishes: - and + and the stamps dim, the enso keeps turning with a stop mark in it */\n#lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){opacity:.45}\n#lzApp.sk-bar :is(#lzMinus,#lzPlus,#lzFast,#lzAuto):disabled{opacity:.45}\n#lzApp:has(#lzAction.busy) .sk-buy{opacity:.62}\n#lzApp:has(#lzAction.busy) .sk-ink{opacity:.72}\n#lzApp.sk-bar #lzAction.busy .sk-enso{opacity:1;transform:none;animation:skTurn 1.4s linear infinite}\n#lzApp.sk-bar #lzAction.busy .sk-stop{opacity:.85;transform:scale(.4)}\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){visibility:hidden} }\n/* the film koi: on the side scroll its rice paper melts into the scroll's paper (multiply) */\n.sk-koiv{position:absolute;z-index:1;pointer-events:none;overflow:hidden;mix-blend-mode:multiply}\n.sk-koiv video{width:100%;height:100%;object-fit:cover;display:block;transition:filter .5s ease}\n.sk-koiv.tall{mix-blend-mode:normal;border-top:9px solid transparent;border-bottom:9px solid transparent;border-image:url(assets/board/rod.webp) 30 0 stretch}\n.sk-koiv.win video{animation:skKoiDart 1.2s ease-out}\n.sk-koiv.big video,.sk-koiv.gold video{filter:sepia(1) saturate(3.4) hue-rotate(-14deg) brightness(1.06) contrast(1.05)}\n.sk-koiv.big{animation:skKoiLeap 1.6s cubic-bezier(.3,1.4,.4,1) 2}\n.sk-koiv.dive video{opacity:.55;transition:opacity .4s}\n@keyframes skKoiDart{0%{transform:none}25%{transform:translateY(-4%) scale(1.03)}100%{transform:none}}\n@keyframes skKoiLeap{0%,100%{transform:none}40%{transform:translateY(-3%) scale(1.06)}}\n@media (prefers-reduced-motion:reduce){ .sk-koiv.big,.sk-koiv.win video{animation:none} }\n/* drops left: one painted drop and the count, on a paper tag */\n.sk-drops{flex-direction:row!important;align-items:center;gap:6px;padding:4px 10px 4px 6px;background:rgba(242,234,216,.92);border:2px solid var(--ink);border-radius:4px}\n.sk-dropsrow{max-width:none!important}\n.sk-dropsrow img{width:clamp(20px,3vh,30px)!important;height:auto}\n.sk-dropsn{font-size:clamp(22px,3.4vh,34px)!important;line-height:1}\n.sk-drops.gold{border-color:var(--gold)}\n.sk-drops.tick .sk-dropsrow img{animation:skPop .3s cubic-bezier(.2,1.6,.4,1)}\n@media (max-height:330px){ .sk-drops{padding:2px 5px 2px 3px;gap:3px} .sk-dropsrow img{width:12px!important} .sk-dropsn{font-size:14px!important} }\n/* (the bar's own button rule names ids, so the stage knobs need ids too to win) */\n#lzApp.sk-bar .sk-icons.on-stage :is(#lzInfo,#lzSound){width:clamp(44px,5.6vh,56px);height:clamp(44px,5.6vh,56px);background:rgba(242,234,216,.94);border:2px solid var(--ink);border-radius:50%;box-sizing:border-box}\n@media (max-height:330px){ #lzApp.sk-bar .sk-icons.on-stage :is(#lzInfo,#lzSound){width:30px;height:30px;border-width:1.5px} }\n.sk-buy .lz-feat:disabled{opacity:1}\n/* the stamp's name and price on a dark ink tag, readable over the bright shoji */\n.sk-buy .lz-feat span,.sk-buy .lz-feat small{background:rgba(27,26,24,.86);padding:3px 8px;border-radius:2px}\n.sk-buy .lz-feat span{color:var(--paper)}\n.sk-buy .lz-feat small{color:#e9c97a}\n@media (max-height:330px){ .sk-buy .lz-feat .sk-stamp{width:44px} .sk-buy .lz-feat small{padding:1px 4px} .sk-ink button{min-width:38px;min-height:30px} }\n/* the short win: the amount sits in a turning red enso, on a pale paper veil, and pops when the count lands */\n.sk-small{display:grid;place-items:center;padding:clamp(18px,4vh,40px) clamp(28px,6vh,60px);top:56%}\n.sk-smallenso{position:absolute;inset:-10% -4%;width:108%;height:120%;object-fit:contain;opacity:.9;animation:skTurn 6s linear infinite,skIn .4s ease-out}\n.sk-smallamt{position:relative;font-size:clamp(40px,8vh,84px)}\n.sk-small.done .sk-smallamt{animation:skPop .45s cubic-bezier(.2,1.7,.4,1)}\n/* the film koi keeps its paper: in a win or KOI FEVER only the koi's own colours deepen (no sepia over the whole frame) */\n.sk-koiv.big video,.sk-koiv.gold video{filter:saturate(1.9) contrast(1.06) brightness(1.03)}\n.sk-small{left:50%;transform:translate(-50%,-50%)}\n/* centred with the translate property, so the pop (transform) cannot move it */\n.sk-small{transform:none;translate:-50% -50%}\n.sk-card{transform:none;translate:-50% -50%}\n/* the mid win (from 2x): the amount flies up out of the best cup and lands in a red enso */\n.sk-mid{position:absolute;z-index:4;translate:-50% -50%;display:grid;place-items:center;width:clamp(190px,32vh,330px);aspect-ratio:1;pointer-events:auto}\n.sk-midenso{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;opacity:0;transform:scale(.3) rotate(-90deg)}\n.sk-midink{position:absolute;left:50%;top:50%;width:0;height:0}\n.sk-midamt{position:relative;font-size:clamp(34px,7vh,72px);color:var(--gold);line-height:1;white-space:nowrap}\n.sk-mid.fly .sk-midamt{animation:skMidFly .52s cubic-bezier(.3,.7,.3,1) both}\n.sk-mid.land .sk-midenso{opacity:.95;transform:none;transition:transform .45s cubic-bezier(.2,1.6,.4,1),opacity .15s;animation:skTurn 5s .45s linear infinite}\n.sk-mid.land .sk-midamt{animation:skPop .45s cubic-bezier(.2,1.8,.4,1)}\n.sk-mid.out{animation:skOut .26s ease-in both}\n@keyframes skMidFly{0%{transform:translate(var(--fx),var(--fy)) scale(.3);opacity:.2}60%{opacity:1}100%{transform:none;opacity:1}}\n/* gold-leaf rain (MASTERPIECE, DRAGON GATE) and the great enso behind DRAGON GATE */\n.sk-rain{position:absolute;top:-6%;width:clamp(14px,2.4vh,26px);height:auto;z-index:3;pointer-events:none;scale:var(--s);animation:skRain var(--t) var(--d) cubic-bezier(.5,0,.8,.6) both}\n@keyframes skRain{from{transform:translateY(0) rotate(0)}to{transform:translateY(115vh) rotate(360deg)}}\n.sk-big.dragon .sk-bigin::before{content:\"\";position:absolute;left:50%;top:50%;width:min(120vh,150%);aspect-ratio:1;translate:-50% -50%;background:url(assets/enso/red.webp) center/contain no-repeat;opacity:.55;z-index:-1;animation:skTurn 7s linear infinite}\n/* on the board's paper (phone): the film's paper is lifted to white so the multiply leaves only the koi */\n.sk-koiv.onboard video{filter:brightness(1.12) contrast(1.35) saturate(1.1)}\n.sk-koiv.onboard.gold video,.sk-koiv.onboard.big video{filter:brightness(1.12) contrast(1.35) saturate(1.9)}\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar .lz-wallet .lz-lbl{display:none!important} #lzApp.sk-bar :is(.lz-wallet,.lz-win) b{font-size:15px} }\n/* ---------- fixes from the independent review (2026-11-27) ---------- */\n/* nothing draws over a win title: knobs, stamps and counters step back while a celebration or card is up */\n.sk-stage :is(.sk-buy,.sk-ink,.sk-drops){transition:opacity .25s}\n.sk-stage.sk-celeb :is(.sk-buy,.sk-ink,.sk-drops){opacity:0!important;pointer-events:none}\n/* the PLAY enso sits on a disc of paper, not on the wooden rod */\n#lzApp.sk-bar #lzAction::before{content:\"\";position:absolute;inset:14%;border-radius:50%;background:url(assets/ui/paper.webp) center/160px auto;border:1.5px solid rgba(27,26,24,.25)}\n#lzApp.sk-bar #lzAction>img{z-index:1}\n#lzApp.sk-bar #lzAction span{z-index:2}\n/* on a phone too, - and + only dim while playing; nothing vanishes */\n@media (max-aspect-ratio:1/1){ #lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){visibility:visible;opacity:.45} }\n/* the koi whole inside its scroll; it stays in sight through a celebration (a lighter veil) */\n.sk-koiv video{object-fit:contain}\n.sk-bigdim{background:rgba(242,234,216,.34)}\n.sk-big.hit .sk-bigflash{animation:skFlash .3s ease-out both}\n@keyframes skFlash{0%{opacity:.5}100%{opacity:0}}\n/* amounts of the short and mid wins on a paper disc, readable over the painting */\n.sk-midamt,.sk-smallamt{background:url(assets/ui/paper.webp) center/200px auto;padding:.12em .4em;border:2px solid var(--ink);border-radius:999px}\n/* MAX WIN: a deeper veil of gold and its own scale */\n.sk-big.maxw .sk-bigdim{background:rgba(201,162,74,.28)}\n.sk-big.maxw .sk-bigtitle{transform:scale(1.08)}\n/* the KOI FEVER start card: words over the numerals */\n.sk-cardword{display:block;font:700 clamp(16px,3vh,28px)/1.2 var(--lz-font-display);letter-spacing:.12em;color:var(--paper);background:rgba(27,26,24,.82);padding:4px 14px;margin:0 auto 6px;width:max-content}\n.sk-cardsub{text-align:center;white-space:nowrap}\n\n/* ---------- round 2 after the independent review (2026-11-27) ---------- */\n/* the celebration has no layer of its own any more (the koi film in it blends with the stage); the title stays on top */\n.sk-big{z-index:auto!important}\n.sk-big .sk-bigin{z-index:2}\n/* the koi swims through every big win, behind the title, in a wide arc; it leaps at each new tier */\n.sk-bigkoi{--kw:min(64vw,92vh);position:absolute;z-index:2;left:calc(50% - var(--kw) / 2);top:calc(30% - var(--kw) * .28);width:var(--kw);height:auto;aspect-ratio:854/480;pointer-events:none;opacity:0;mix-blend-mode:multiply;filter:brightness(1.12) contrast(1.35) saturate(1.15);-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}\n.sk-bigkoi.swim{opacity:1;animation:skKoiCross 3.6s cubic-bezier(.45,.05,.55,.95) infinite}\n.sk-bigkoi.swim.leap{animation:skKoiCross 3.6s cubic-bezier(.45,.05,.55,.95) infinite,skKoiHop .7s cubic-bezier(.2,1.4,.4,1)}\n.sk-big.goldk .sk-bigkoi{filter:brightness(1.12) contrast(1.35) saturate(2.4)}\n.sk-big.out .sk-bigkoi{display:none}\n@keyframes skKoiCross{0%{transform:translate(-78vw,9vh) rotate(-13deg)}50%{transform:translate(0,-3vh) rotate(0deg)}100%{transform:translate(78vw,9vh) rotate(13deg)}}\n@keyframes skKoiHop{0%,100%{translate:0 0;scale:1}40%{translate:0 -7vh;scale:1.22}}\n@media (prefers-reduced-motion:reduce){ .sk-bigkoi{display:none} }\n/* on a phone the small koi on the scroll steps aside while the big one swims */\n.sk-stage:has(.sk-big:not([hidden])) .sk-koiv.onboard{opacity:0;transition:opacity .3s}\n/* KOI FEVER bar (7.3): multiplier, golden drops left, the win so far */\n.sk-fbar{position:absolute;z-index:2;translate:-50% 0;display:flex;align-items:center;white-space:nowrap;pointer-events:none;background:url(assets/ui/paper.webp) center/200px auto;border:2px solid var(--gold);border-radius:4px;padding:4px 2px}\n.sk-fbar[hidden]{display:none}\n.sk-fbar.tall{translate:-50% -100%}\n.sk-fbcell{display:flex;align-items:center;gap:6px;padding:0 10px;font-size:clamp(18px,3.6vh,30px);line-height:1}\n.sk-fbcell+.sk-fbcell{border-left:2px solid rgba(27,26,24,.3)}\n.sk-fbcell b{font:700 clamp(10px,1.8vh,14px)/1 var(--lz-font-display);letter-spacing:.14em;color:var(--ink)}\n.sk-fbcell img{width:.9em;height:.9em;object-fit:contain}\n.sk-fbar.tick .sk-fbcell:last-child .sk-fbv{animation:skPop .3s cubic-bezier(.2,1.6,.4,1)}\n.sk-fbar.tall .sk-fbcell{padding:0 6px;font-size:19px;gap:4px}\n.sk-fbar.tall .sk-fbcell b{font-size:10px;letter-spacing:.08em}\n/* in KOI FEVER the bar says it all: the drops tag, the ink switch and the stamp step out (nothing to choose mid-feature) */\n.sk-stage.sk-on-fever :is(.sk-drops,.sk-buy,.sk-ink){opacity:0!important;pointer-events:none}\n/* the KOI FEVER start card waits for a tap */\n.sk-cardtap{margin-top:1.4vh;font:700 clamp(14px,2.6vh,22px)/1 var(--lz-font-display);letter-spacing:.2em;color:var(--ink);background:url(assets/ui/paper.webp) center/200px auto;border:2px solid var(--ink);border-radius:4px;padding:8px 18px;animation:skBlink 1.2s ease-in-out infinite}\n@keyframes skBlink{50%{opacity:.5}}\n/* phone: the balance has its word over it, like WIN */\n@media (max-aspect-ratio:1/1) and (min-height:560px){ #lzApp.sk-bar .lz-wallet .lz-lbl{display:block!important;font-size:10px;letter-spacing:.14em;margin:0 0 2px} }\n/* the koi leaps over the title (in front of it, in the band above), so it is seen, not hidden behind the letters */\n.sk-bigkoi{--kw:min(54vw,76vh);z-index:3;top:calc(15% - var(--kw) * .28)}\n.sk-fbcell{font-size:clamp(22px,4.6vh,36px)}\n.sk-fbcell b{font-size:clamp(11px,2vh,16px)}\n/* the app takes no layer of its own: the koi films (multiply) blend with the painted room behind it, not with an empty layer */\n#lzApp.lz-app.sk-bar{z-index:auto}\n/* the brush that paints a title on starts left of it, so its tapered end never eats the first letter (\"EVER WIN\") */\n.sk-big.hit .sk-bigtitle,.sk-big.up .sk-bigtitle,.sk-card.in img{-webkit-mask-position:15% 50%;mask-position:15% 50%}\n/* while a big win gathers, a light veil only (the review saw a white void) */\n.sk-big.pre .sk-bigdim{opacity:.45}\n/* phone: the koi swims bigger, in the open band between the top of the screen and the title */\n@media (max-aspect-ratio:1/1){ .sk-bigkoi{--kw:86vw;top:calc(21% - var(--kw) * .28)} }\n\n/* ---------- round 3, after the second independent review (2026-11-27) ---------- */\n/* 4. while a big win plays, the bar and the corner knobs step back (dimmed, still there), and the win sits higher */\n#lzApp:has(.sk-big:not([hidden])) :is(.lz-panel,.sk-icons){opacity:.38;transition:opacity .3s}\n#lzApp :is(.lz-panel,.sk-icons){transition:opacity .3s}\n.sk-big{padding-bottom:min(12vh,96px);box-sizing:border-box}\n/* 5. the amount of a big win: large, on a paper disc with an ink rim, readable over any painting */\n.sk-bigamt{font-size:clamp(46px,12vh,130px);background:url(assets/ui/paper.webp) center/220px auto;border:3px solid var(--ink);border-radius:999px;padding:.06em .5em .1em}\n.sk-big .sk-bigin{gap:.6vh}\n/* MAX WIN: the multiplier under the amount */\n.sk-bigx{font-size:clamp(28px,6.5vh,64px);line-height:1;background:url(assets/ui/paper.webp) center/200px auto;border:2px solid var(--red,#c8372d);border-radius:4px;padding:.04em .35em;opacity:0}\n.sk-bigx[hidden]{display:none}\n.sk-big.count .sk-bigx,.sk-big.slam .sk-bigx{opacity:1}\n.sk-big.slam .sk-bigx{animation:skPop .5s cubic-bezier(.2,1.7,.4,1)}\n/* the mid win from 3x: gold enso, larger */\n.sk-mid.strong{width:clamp(220px,40vh,400px)}\n.sk-mid.strong .sk-midenso{filter:sepia(1) saturate(4) hue-rotate(-12deg) brightness(1.05)}\n.sk-mid.strong .sk-midamt{font-size:clamp(40px,8.5vh,86px)}\n/* 7. the moment before KOI FEVER: the view closes on the seal and the room goes dark */\n.sk-stage{transition:transform .45s cubic-bezier(.3,0,.2,1)}\n.sk-stage.sk-tease{transform:scale(1.09);transform-origin:var(--tx,50%) var(--ty,40%);transition:transform 1.5s cubic-bezier(.3,0,.2,1)}\n.sk-bg{transition:filter .6s}\nbody:has(.sk-stage.sk-tease) .sk-bg{filter:brightness(.42) saturate(.8)}\n@media (prefers-reduced-motion:reduce){ .sk-stage.sk-tease{transform:none} }\n/* 2. the koi lives in its scroll: a slow drift up and down; its film's paper melts into the scroll */\n.sk-koiv:not(.onboard) video{translate:0 0;animation:skKoiDrift 11s ease-in-out infinite;-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;filter:brightness(1.06) contrast(1.12)}\n@keyframes skKoiDrift{0%,100%{translate:0 -7%}50%{translate:0 7%}}\n.sk-koiv.dive video{transform:translateY(9%) scale(.94);transition:transform .5s ease-in,opacity .4s}\n@media (prefers-reduced-motion:reduce){ .sk-koiv video{animation:none!important} }\n/* 13. volatility in the intro */\n.sk-vol{display:flex;align-items:center;justify-content:center;gap:10px;margin:.6em 0 .2em;font:700 13px/1 var(--lz-font-display);letter-spacing:.16em;color:var(--ink)}\n.sk-volbar{display:inline-flex;gap:4px}\n.sk-volbar img{width:16px;height:16px;object-fit:contain;opacity:.3}\n.sk-volbar img.on{opacity:1}\n/* 14. phone: BALANCE at the 12 px minimum */\n@media (max-aspect-ratio:1/1) and (min-height:560px){ #lzApp.sk-bar .lz-wallet .lz-lbl{font-size:12px;letter-spacing:.1em} }\n/* the big win fits above the bar on a short landscape screen: the title is sized by the height too */\n.sk-big .sk-bigin,.sk-big.t3 .sk-bigin{width:min(88%,820px,112vh)}\n/* the koi's own reactions in its scroll (not only its speed): a big win or KOI FEVER - it gathers, leaps and somersaults,\n   then settles; a win - a dart up; a loss - it sinks and pales */\n.sk-koiv.big{animation:none}\n.sk-koiv.big video{animation:skKoiFlip 1.5s cubic-bezier(.35,0,.25,1) 1,skKoiDrift 11s ease-in-out infinite}\n@keyframes skKoiFlip{0%{transform:none}18%{transform:translateY(6%) scale(.96)}45%{transform:translateY(-20%) rotate(160deg) scale(1.12)}75%{transform:translateY(-10%) rotate(330deg) scale(1.06)}100%{transform:rotate(360deg)}}\n.sk-koiv.win video{animation:skKoiDart 1.2s ease-out,skKoiDrift 11s ease-in-out infinite}\n@media (prefers-reduced-motion:reduce){ .sk-koiv.big video,.sk-koiv.win video{animation:none} }\n.sk-ksplash{position:absolute;z-index:2;width:clamp(26px,5vh,54px);height:auto;pointer-events:none;translate:-50% -50%;rotate:var(--r);opacity:0;animation:skKSplash .9s var(--d) cubic-bezier(.2,.9,.3,1) both;filter:brightness(0)}\n.sk-ksplash.gold{filter:sepia(1) saturate(4) hue-rotate(-12deg) brightness(.95)}\n@keyframes skKSplash{0%{opacity:0;scale:.2}25%{opacity:.9}100%{opacity:0;scale:1.4}}\n\n/* ---------- round 4, after the third independent review (2026-11-27) ---------- */\n/* nothing vanishes: in a celebration and in KOI FEVER the stamp, the ink switch and the drops tag only dim (and lock) */\n.sk-stage.sk-celeb :is(.sk-buy,.sk-ink,.sk-drops){opacity:.28!important;pointer-events:none}\n.sk-stage.sk-on-fever :is(.sk-buy,.sk-ink){opacity:.28!important;pointer-events:none}\n.sk-stage.sk-on-fever .sk-drops{opacity:0!important}\n/* the big win: a dark ink veil (not a white haze), coloured by tier; the amount gold on a dark ink disc with a gold rim */\n.sk-bigdim,.sk-big .sk-bigdim{background:rgba(20,18,16,.62)}\n.sk-big.t1 .sk-bigdim{background:rgba(48,14,12,.6)}\n.sk-big.t2 .sk-bigdim{background:rgba(40,30,8,.62)}\n.sk-big.t3 .sk-bigdim,.sk-big.maxw .sk-bigdim{background:rgba(58,10,8,.64)}\n.sk-big.pre .sk-bigdim{opacity:.7}\n.sk-bigamt{background:rgba(20,18,16,.86);border:3px solid var(--gold);font-size:clamp(52px,14vh,150px)}\n.sk-big.maxw.count .sk-bigamt{animation:skBump .25s ease-out infinite}\n@keyframes skBump{0%{scale:1}40%{scale:1.06}100%{scale:1}}\n/* the bigkoi film multiplies its paper away: over a dark veil it must not darken, so it screens in light instead */\n.sk-bigkoi{mix-blend-mode:normal;filter:brightness(1.12) contrast(1.35) saturate(1.15)}\n/* the KOI FEVER cards: the words and amounts on dark ink, and the start card above the cup values */\n.sk-card{top:36%}\n.sk-cardsub .skd{filter:none}\n.sk-cardsub{background:rgba(20,18,16,.84);border:2px solid var(--gold);border-radius:999px;padding:.08em .5em .12em;width:max-content;margin:0 auto}\n/* a win rising from its cup in KOI FEVER */\n.sk-plus{position:absolute;z-index:3;translate:-50% -100%;font-size:clamp(16px,3vh,28px);line-height:1;white-space:nowrap;pointer-events:none;background:rgba(20,18,16,.78);border-radius:999px;padding:.08em .35em;animation:skPlus 1.1s ease-out both}\n.sk-plus.big{font-size:clamp(26px,5.5vh,52px);border:2px solid var(--gold);animation:skPlusBig 1.7s cubic-bezier(.2,1.4,.4,1) both}\n@keyframes skPlus{0%{opacity:0;transform:translateY(10px) scale(.7)}20%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-60px)}}\n@keyframes skPlusBig{0%{opacity:0;transform:scale(.3)}25%{opacity:1;transform:scale(1.15)}40%{transform:scale(1)}100%{opacity:0;transform:translateY(-90px)}}\n/* the bet bar in KOI FEVER: the feature in place of the amount */\n.sk-bonusflag{display:none}\n#lzApp:has(.sk-on-fever) .sk-bonusflag{display:flex;align-items:center;justify-content:center;gap:6px;position:absolute;inset:0;background:rgba(20,18,16,.92);border:2px solid var(--gold);border-radius:4px;color:var(--paper);font:700 12px/1 var(--lz-font-display);letter-spacing:.1em;white-space:nowrap;font-size:12px;z-index:2}\n#lzApp:has(.sk-on-fever) .sk-bonusflag .skd{font-size:20px}\n#lzApp:has(.sk-on-fever) .sk-bonusflag b{color:var(--gold)}\n#lzApp:has(.sk-on-fever) #lzField{position:relative}\n/* veils by tier: the ink and red titles on a dusk paper veil (not white), the gold ones on a dark one */\n.sk-bigdim,.sk-big .sk-bigdim,.sk-big.t1 .sk-bigdim,.sk-big.t3 .sk-bigdim{background:rgba(196,182,156,.58)}\n.sk-big.t2 .sk-bigdim,.sk-big.maxw .sk-bigdim{background:rgba(34,24,10,.55)}\n.sk-bigkoi{mix-blend-mode:multiply}\n/* the KOI FEVER flag stands over the amount (which hides under it), centred and as wide as its words */\n#lzApp:has(.sk-on-fever) .sk-bonusflag{inset:auto;left:50%;top:50%;translate:-50% -50%;padding:6px 10px;width:max-content;z-index:5}\n#lzApp:has(.sk-on-fever) #lzField .lz-amount{visibility:hidden}\n@media (max-width:480px){ #lzApp:has(.sk-on-fever) .sk-bonusflag{font-size:10px;gap:4px;padding:5px 7px;letter-spacing:.04em} #lzApp:has(.sk-on-fever) .sk-bonusflag .skd{font-size:16px} }\n\n/* the koi's drawn leap over its swim loop; the drift moves the whole film box, so both clips stay in step */\n.sk-koiv video.leap{position:absolute;inset:0;opacity:0;transition:opacity .12s}\n.sk-koiv.leaping video.leap{opacity:1}\n.sk-koiv.leaping video:not(.leap){opacity:0}\n.sk-koiv:not(.onboard) video{animation:none;translate:none}\n.sk-koiv:not(.onboard){animation:skKoiDrift 11s ease-in-out infinite}\n.sk-koiv.big:not(.onboard){animation:skKoiDrift 11s ease-in-out infinite}\n.sk-koiv.big video:not(.leap){animation:skKoiFlip 1.5s cubic-bezier(.35,0,.25,1) 1}\n.sk-koiv.win video:not(.leap){animation:skKoiDart 1.2s ease-out}\n.sk-koiv:not(.onboard) video.leap{-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;filter:brightness(1.06) contrast(1.12)}\n.sk-koiv.gold video.leap{filter:saturate(1.9) contrast(1.06) brightness(1.03)}\n@media (prefers-reduced-motion:reduce){ .sk-koiv:not(.onboard){animation:none} }\n\n/* ---------- KOI SPRING (math v2) ---------- */\n.sk-swimkoi{position:absolute;left:0;top:0;z-index:3;width:clamp(90px,17vh,170px);height:auto;pointer-events:none;will-change:transform}\n.sk-swimkoi.golden{width:clamp(200px,40vh,420px);z-index:4;filter:saturate(1.3) brightness(1.08)}\n.sk-goldx{position:absolute;z-index:5;translate:-50% -50%;font-size:clamp(60px,15vh,150px);line-height:1;background:rgba(20,18,16,.85);border:3px solid var(--gold);border-radius:999px;padding:.04em .4em .08em;pointer-events:none;animation:skGoldX 1.9s cubic-bezier(.2,1.6,.4,1) both}\n@keyframes skGoldX{0%{opacity:0;scale:2.4}18%{opacity:1;scale:.92}30%{scale:1}85%{opacity:1}100%{opacity:0;scale:1.1}}\n.sk-cardtitle{display:block;font:700 clamp(44px,11vh,110px)/1 var(--lz-font-display);letter-spacing:.06em;color:var(--red,#c8372d);-webkit-text-stroke:3px #1b1a18;paint-order:stroke fill;margin:0 0 .12em}\n.sk-card:has(img[hidden]) .sk-cardsub{background:rgba(20,18,16,.84);padding:.2em .6em .3em}\n.sk-card:has(img[hidden]) .sk-cardtitle{-webkit-text-stroke:0;color:#e04a3a}\n.sk-fbar.spring{border-color:var(--red,#c8372d)}\n@media (prefers-reduced-motion:reduce){ .sk-swimkoi{display:none} }\n.sk-swimkoi{width:clamp(120px,26vh,260px)}\n.sk-goldx{white-space:nowrap;width:max-content}\n@media (max-aspect-ratio:1/1){ .sk-goldx{font-size:clamp(48px,10vh,96px)} }\n/* phone: the moment before the seal opens darkens the room only (no zoom of the whole stage: too heavy for a slow phone) */\n@media (max-aspect-ratio:1/1){ .sk-stage.sk-tease{transform:none} }\n.sk-swimkoi{will-change:auto}\n\n/* ---------- KOI SPRING: the waterfall climb (2026-11-28) ---------- */\n.sk-wf{position:absolute;inset:0;z-index:4}\n.sk-wf[hidden]{display:none}\n.sk-wfveil{position:absolute;inset:0;background:rgba(14,12,10,.84)}\n.sk-wfpanel{position:absolute;top:50%;translate:-50% -50%;overflow:hidden;border:3px solid #1b1a18;border-radius:4px;background:url(assets/spring/waterfall.webp) center/cover no-repeat}\n.sk-wf.in .sk-wfpanel{animation:skWfIn .6s cubic-bezier(.2,1.2,.4,1) both}\n@keyframes skWfIn{from{opacity:0;scale:.86}to{opacity:1;scale:1}}\n.sk-wf.out{animation:skOut .38s ease-in both}\n.sk-wfvid{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}\n.sk-wfrungs{position:absolute;inset:0;pointer-events:none}\n.sk-wfrung{position:absolute;right:3%;translate:0 -50%;font-size:clamp(15px,2.8vh,26px);line-height:1;background:rgba(242,234,216,.88);border:2px solid #1b1a18;border-radius:999px;padding:.08em .4em;opacity:.8;transition:opacity .25s,scale .25s}\n.sk-wfrung.done{opacity:.35}\n.sk-wfrung.now{opacity:1;scale:1.3;border-color:var(--red,#c8372d);border-width:3px}\n.sk-wfkoi{position:absolute;left:50%;width:24%;height:auto;translate:-50% -50%;rotate:-90deg;pointer-events:none}\n.sk-wfkoi.enter{opacity:.9}\n.sk-wfkoi.ready{animation:skKoiReady .32s ease-in-out infinite}\n.sk-wfkoi.jump{scale:1.12}\n.sk-wfkoi.slip{animation:skKoiSlip .14s linear infinite}\n.sk-wfkoi.fall{rotate:-150deg;scale:.95;transition:rotate .4s ease-in}\n.sk-wfkoi.gold{filter:sepia(1) saturate(4) hue-rotate(-12deg) brightness(1.1)}\n@keyframes skKoiReady{0%,100%{scale:1 1}50%{scale:.92 1.06}}\n@keyframes skKoiSlip{0%,100%{translate:-50% -50%}25%{translate:-56% -48%}75%{translate:-44% -52%}}\n.sk-wfdragon{position:absolute;left:50%;top:4%;width:92%;height:auto;translate:-50% 0;opacity:0;scale:.2;pointer-events:none}\n.sk-wfdragon.rise{animation:skDragon 1.6s cubic-bezier(.2,1.3,.4,1) forwards}\n@keyframes skDragon{0%{opacity:0;scale:.2;translate:-50% 30%;rotate:-20deg}40%{opacity:1}100%{opacity:1;scale:1;translate:-50% 0;rotate:0deg}}\n.sk-wf.gate .sk-wfpanel::after{content:\"\";position:absolute;inset:0;background:rgba(255,226,150,.55);pointer-events:none;animation:skFlash .7s ease-out both}\n.sk-wfink{position:absolute;inset:0;pointer-events:none}\n.sk-wfsplash{position:absolute;width:16%;height:auto;translate:-50% -50%;rotate:var(--r);filter:brightness(0) invert(1);opacity:0;animation:skKSplash .8s ease-out both}\n.sk-wfprize{position:absolute;left:50%;bottom:2.5%;translate:-50% 0;font-size:clamp(30px,7vh,64px);line-height:1;white-space:nowrap;background:rgba(20,18,16,.88);border:3px solid var(--gold);border-radius:999px;padding:.06em .5em .1em}\n.sk-wfprize.tick{animation:skPop .35s cubic-bezier(.2,1.7,.4,1)}\n.sk-goldx.word{font:700 clamp(30px,6vh,60px)/1 var(--lz-font-display);color:var(--gold);letter-spacing:.08em;padding:.25em .6em}\n@media (prefers-reduced-motion:reduce){ .sk-wfkoi.ready,.sk-wfkoi.slip{animation:none} }\n.sk-wf{z-index:30}\n.sk-wfkoi{width:36%}\n.sk-wfrung{font-size:clamp(17px,3.2vh,30px)}\n/* the climbing koi: the drawn leap clip in a box that rises; its paper melts into the falls (multiply, soft edges) */\n.sk-wfkoi{width:30%;height:auto;aspect-ratio:540/960;rotate:none;mix-blend-mode:multiply;animation:none!important}\n.sk-wfkoi video{width:100%;height:100%;object-fit:contain;display:block;filter:brightness(1.14) contrast(1.4) saturate(1.15);-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%}\n.sk-wfkoi.rest{animation:skKoiHold 2.6s ease-in-out infinite!important}\n@keyframes skKoiHold{0%,100%{translate:-50% -50%}50%{translate:-50% -52.5%}}\n.sk-wfkoi.gold video{filter:brightness(1.14) contrast(1.4) sepia(.85) saturate(3.4) hue-rotate(-12deg)}\n.sk-wfkoi.fall{scale:.92}\n.sk-wfkoi.gone{opacity:0;transition:opacity .2s}\n.sk-wfkoi.up,.sk-wfkoi.jump,.sk-wfkoi.slip,.sk-wfkoi.ready{scale:none}\n.sk-wfkoi{width:46%}\n.sk-wfkoi video{filter:brightness(1.1) contrast(1.6) saturate(1.35)}\n.sk-wfkoi.gold video{filter:brightness(1.1) contrast(1.6) sepia(.85) saturate(3.6) hue-rotate(-12deg)}\n.sk-wfprize{bottom:1.5%;font-size:clamp(26px,5.6vh,54px)}\n\n/* ---------- v3: the sleeping dragon, the ink events ---------- */\n.sk-dragonb{position:absolute;z-index:1;pointer-events:none;transform-origin:85% 50%}\n.sk-dragonb img{width:100%;height:auto;display:block;filter:saturate(.6) brightness(.92);transition:filter .5s;animation:skBreath 4.6s ease-in-out infinite}\n@keyframes skBreath{0%,100%{scale:1 1}50%{scale:1.012 1.03}}\n.sk-dreye{position:absolute;left:87.5%;top:43%;width:2.6%;aspect-ratio:1;border-radius:50%;background:#ffd76a;opacity:0;translate:-50% -50%;transition:opacity .3s}\n.sk-dragonb.stir img{animation:skStir .55s ease-in-out,skBreath 3.2s ease-in-out .55s infinite;filter:saturate(.85) brightness(1)}\n.sk-dragonb.stir .sk-dreye{opacity:.55;animation:skBlinkEye 1.6s ease-in-out infinite}\n.sk-dragonb.wake img{animation:skStir .5s ease-in-out 2,skBreath 1.6s ease-in-out 1s infinite;filter:saturate(1.25) brightness(1.08)}\n.sk-dragonb.wake .sk-dreye{opacity:1;width:3.4%;animation:skBlinkEye .7s ease-in-out infinite}\n.sk-dragonb.rise{animation:skRise 1.1s cubic-bezier(.5,0,.3,1) forwards}\n.sk-dragonb.rise img{filter:saturate(1.4) brightness(1.15)}\n@keyframes skStir{0%,100%{translate:0 0;rotate:0deg}30%{translate:-1% -3%;rotate:-1deg}60%{translate:1% 1%;rotate:.6deg}}\n@keyframes skBlinkEye{0%,100%{opacity:1;scale:1}50%{opacity:.6;scale:.7}}\n@keyframes skRise{0%{transform:none;opacity:1}35%{transform:translateY(8%) scale(1.04)}100%{transform:translateY(-140%) scale(1.25);opacity:0}}\n.sk-puff{position:absolute;z-index:2;width:clamp(16px,3vh,30px);height:auto;translate:-50% -50%;pointer-events:none;filter:grayscale(1) brightness(1.6);opacity:0;animation:skPuff 1.4s var(--d) ease-out both}\n@keyframes skPuff{0%{opacity:0;transform:translate(0,0) scale(.4)}30%{opacity:.55}100%{opacity:0;transform:translate(14px,-40px) scale(1.6)}}\n/* on a phone the top of the scroll is the dragon's: the small film koi steps aside (the pond koi and the falls carry the koi) */\n.sk-koiv.onboard{display:none}\n/* the ink event ribbon */\n.sk-evb{position:absolute;z-index:4;left:50%;top:40%;translate:-50% -50%;display:flex;flex-direction:column;align-items:center;gap:.25em;pointer-events:none;padding:.35em 1.1em .45em;background:rgba(20,18,16,.86);border:3px solid var(--gold);border-radius:6px;white-space:nowrap}\n.sk-evb[hidden]{display:none}\n.sk-evb b{font:700 clamp(26px,6vh,56px)/1 var(--lz-font-display);letter-spacing:.08em;color:var(--gold)}\n.sk-evb.red{border-color:var(--red,#c8372d)} .sk-evb.red b{color:#e04a3a}\n.sk-evb span{font-size:clamp(26px,5vh,48px);line-height:1;display:flex;align-items:center;gap:.3em}\n.sk-evbsmall{font:700 clamp(11px,1.9vh,16px)/1 var(--lz-font-display);letter-spacing:.14em;color:var(--paper)}\n.sk-evb.in{animation:skEvIn .45s cubic-bezier(.2,1.5,.4,1) both}\n.sk-evb.out{animation:skOut .26s ease-in both}\n@keyframes skEvIn{0%{opacity:0;scale:.5 .2}60%{opacity:1;scale:1.06 1}100%{scale:1}}\n/* the gold cup's tag and the hungry seal */\n.sk-gctag{position:absolute;z-index:3;translate:-50% 0;font-size:clamp(16px,3vh,28px);line-height:1;background:rgba(20,18,16,.88);border:2px solid var(--gold);border-radius:999px;padding:.08em .35em;pointer-events:none;animation:skPop .4s cubic-bezier(.2,1.7,.4,1),skGcPulse 1.2s ease-in-out .4s infinite}\n@keyframes skGcPulse{0%,100%{scale:1}50%{scale:1.12}}\n.sk-hungry{position:absolute;z-index:2;translate:-50% -50%;aspect-ratio:1;height:auto;pointer-events:none;opacity:.85;animation:skTurn 2.4s linear infinite,skHungry 1s ease-in-out infinite}\n@keyframes skHungry{0%,100%{scale:1}50%{scale:1.1}}\n.sk-drops.golden{border-color:var(--gold);animation:skGcPulse 1s ease-in-out infinite}\n.sk-swimkoi.touch{width:clamp(110px,22vh,220px)}\n/* the intro: the sleeping dragon over the notes */\n.sk-introdragon{display:block;width:min(78%,380px);height:auto;margin:.2em auto .1em;animation:skBreath 4.6s ease-in-out infinite}\n.sk-notes img[src*=\"spring/\"]{object-fit:cover;border-radius:4px}\n@media (prefers-reduced-motion:reduce){ .sk-dragonb img,.sk-introdragon,.sk-hungry,.sk-gctag{animation:none!important} }\n.sk-evb{max-width:92%;white-space:normal;text-align:center}\n.sk-evb b{font-size:clamp(22px,min(6vh,8vw),56px)}\n.sk-evb span{flex-wrap:wrap;justify-content:center;font-size:clamp(22px,min(5vh,7vw),48px)}\n.sk-evbsmall{font-size:clamp(10px,min(1.9vh,3vw),16px)}\n/* v3 climb: the koi fights the current (the struggle film), the dragon sleeps over the gate, wakes, and rises (its film) */\n.sk-wfkoi{width:40%}\n.sk-wfkoi video{position:absolute;inset:0}\n.sk-wfkoi video.leap{opacity:0}\n.sk-wfkoi.leaping video.leap{opacity:1} .sk-wfkoi.leaping video.swim{opacity:0}\n.sk-wfkoi.hold{animation:skAgainst 1.4s ease-in-out infinite!important}\n@keyframes skAgainst{0%,100%{translate:-50% -50%}45%{translate:-50% -46%}70%{translate:-50% -48.5%}}\n.sk-wfkoi.surge{scale:1.05}\n.sk-wfkoi.pushed{animation:skKoiSlip .14s linear 3!important}\n.sk-wfkoi.swept{rotate:-18deg;transition:rotate .3s}\n.sk-wfkoi.glint video{filter:brightness(1.1) contrast(1.6) sepia(.85) saturate(3.6) hue-rotate(-12deg)!important;transition:filter .15s}\n.sk-wfsleep{position:absolute;left:50%;top:1.5%;width:62%;height:auto;translate:-50% 0;pointer-events:none;filter:saturate(.55) brightness(.9);animation:skBreath 4.6s ease-in-out infinite;transition:filter .5s,opacity .3s}\n.sk-wfsleep.stir{filter:saturate(.9) brightness(1);animation:skStir .55s ease-in-out,skBreath 2.6s ease-in-out .55s infinite}\n.sk-wfsleep.wake{filter:saturate(1.3) brightness(1.1);animation:skStir .5s ease-in-out 2,skBreath 1.4s ease-in-out 1s infinite}\n.sk-wfsleep.gone{opacity:0}\n.sk-wfwake{position:absolute;left:50%;top:22%;width:150%;height:auto;aspect-ratio:16/9;translate:-50% -50%;pointer-events:none;opacity:0;mix-blend-mode:multiply;filter:brightness(1.1) contrast(1.3) saturate(1.2);-webkit-mask-image:url(data:image/webp;base64,);mask-image:url(data:image/webp;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%}\n.sk-wfwake.on{opacity:1;top:36%;transition:opacity .25s,top 3.2s cubic-bezier(.3,.1,.3,1)}\n.sk-wfdragon{display:none}\n/* gold without staining the film's paper: richer colour and gold sparks around the koi (no sepia) */\n.sk-wfkoi.gold video,.sk-wfkoi.glint video{filter:brightness(1.16) contrast(1.6) saturate(2.3)!important}\n.sk-wfkoi.gold::after,.sk-wfkoi.glint::after{content:\"\";position:absolute;inset:10% 20%;background:url(assets/drops/gold.webp) 20% 30%/18% auto no-repeat,url(assets/drops/gold.webp) 80% 60%/14% auto no-repeat,url(assets/drops/gold.webp) 40% 85%/12% auto no-repeat,url(assets/drops/gold.webp) 70% 15%/10% auto no-repeat;animation:skSpark .5s ease-in-out infinite alternate;pointer-events:none}\n@keyframes skSpark{from{opacity:.35;scale:.9}to{opacity:1;scale:1.08}}\n.sk-wf.gate .sk-wfrungs{opacity:0;transition:opacity .3s}\n/* KOI SPRING to buy: its stamp shows the falls; one ink's stamp at a time, like KOI FEVER */\n:root:not([data-ink=\"wild\"]) .sk-buy .lz-feat[data-mode=\"wildspring\"],:root[data-ink=\"wild\"] .sk-buy .lz-feat[data-mode=\"spring\"]{display:none!important}\n.sk-buy .lz-feat .sk-stamp.spring{object-fit:cover;object-position:50% 10%}\n/* two stamps now (KOI SPRING and KOI FEVER), side by side: each sized so the pair fits the column on any screen */\n.sk-buy .lz-feat .sk-stamp{width:clamp(50px,min(10.5vh,7vw),108px)}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat .sk-stamp{width:clamp(50px,13vw,80px)}\n.sk-buy .lz-feat span,.sk-buy .lz-feat small{font-size:clamp(10px,1.7vh,14px)!important}\n/* the intro's sleeping dragon only where there is height for it */\n@media (max-height:520px){ .sk-introdragon{display:none} }\n/* the stamp labels at the minimum size (16px on 1024x576, 12px on 400x225) */\n.sk-buy .lz-feat span,.sk-buy .lz-feat small{font-size:clamp(12px,2.8vh,16px)!important;white-space:normal;line-height:1.05}\n.sk-wfdragon{display:block}\n/* phone: two small stamps side by side in the top right, labels at the 12 px minimum */\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat .sk-stamp{width:44px}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat span,.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feat small{font-size:12px!important;letter-spacing:.04em}\n.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy .lz-feats,.sk-stage:has(.sk-hud[data-wide=\"0\"]) .sk-buy{gap:4px}\n/* the dragon's smoke: plain ink, no filter (cheaper on slow phones) */\n.sk-puff{filter:none;opacity:0}\n\n/* ---------- the frenzy: one canvas over the whole window ---------- */\n.sk-fx{position:fixed;left:0;top:0;width:100vw;height:100vh;pointer-events:none;z-index:60}\n#lzWin.sk-pop{animation:skPop .22s cubic-bezier(.2,1.8,.4,1)}\n/* ---------- v4 climb: lives, pearls, multiplier ---------- */\n.sk-wflives{position:absolute;left:3%;top:3%;display:flex;gap:4px;z-index:2;background:rgba(20,18,16,.75);border:2px solid var(--gold);border-radius:999px;padding:4px 8px}\n.sk-wflives img{width:clamp(22px,4.2vh,38px);height:auto;transition:opacity .25s,filter .25s}\n.sk-wflives img.lost{opacity:.22;filter:grayscale(1)}\n.sk-wflives.lastlife{animation:skLast .5s ease-in-out infinite;border-color:#e04a3a}\n@keyframes skLast{0%,100%{scale:1}50%{scale:1.1}}\n.sk-wfmult{position:absolute;right:3%;top:3%;z-index:2;font-size:clamp(24px,5vh,46px);line-height:1;background:rgba(20,18,16,.85);border:2px solid var(--gold);border-radius:999px;padding:.08em .4em}\n.sk-wfmult.tick{animation:skPop .4s cubic-bezier(.2,1.8,.4,1)}\n.sk-wfpearls{position:absolute;inset:0;pointer-events:none}\n.sk-wfpearl{position:absolute;left:22%;translate:-50% -50%;display:flex;align-items:center;gap:2px;font-size:clamp(14px,2.6vh,24px);animation:skPearl 1.6s ease-in-out infinite;transition:opacity .3s,scale .3s}\n.sk-wfpearl img{width:clamp(22px,4.4vh,40px);height:auto}\n.sk-wfpearl span{background:rgba(20,18,16,.8);border-radius:999px;padding:.04em .3em}\n.sk-wfpearl.dragon img{width:clamp(36px,7vh,62px)}\n.sk-wfpearl.taken{opacity:0;scale:2.2}\n@keyframes skPearl{0%,100%{translate:-50% -50%}50%{translate:-50% -60%}}\n.sk-wfrung{font-size:clamp(14px,2.5vh,24px)}\n/* light on a slow phone: the hungry seal pulses without turning, the ribbon only fades, no smoke */\n@media (max-aspect-ratio:1/1){\n  .sk-hungry{animation:skHungry 1s ease-in-out infinite}\n  .sk-evb.in{animation:skFadeIn .25s ease-out both}\n  .sk-puff{display:none}\n  .sk-dragonb img{animation:none}\n  .sk-dragonb.stir img,.sk-dragonb.wake img{animation:skStir .55s ease-in-out}\n}\n@keyframes skFadeIn{from{opacity:0}to{opacity:1}}\n@media (max-aspect-ratio:1/1){ .sk-big.dragon .sk-bigin::before{animation:none} .sk-big.maxw.count .sk-bigamt{animation:none} }\n/* the confirm buttons of the panels (Start autoplay, Start / Open a feature): red ink with paper letters, never blank */\n.lz-modal .lz-btns .lz-go,#lzApStart{background:var(--lz-accent)!important;color:var(--lz-accent-ink)!important;border:2px solid var(--lz-accent)!important}\n/* ---------- the buy cards (wide screens): bigger, framed in paper, the same size, the price on a red tag ---------- (only where there is height for them) */\n@media (min-height:480px){\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feats{gap:clamp(8px,1.6vw,18px);align-items:start}\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feat{width:auto!important;padding:clamp(4px,.8vh,8px);gap:clamp(3px,.8vh,8px);background:url(assets/ui/paper.webp) center/220px auto;border:3px solid var(--red,#c8372d);border-radius:6px;transition:transform .18s cubic-bezier(.2,1.6,.4,1)}\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feat:hover{transform:translateY(-4px) rotate(-1deg)}\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feat .sk-stamp{width:clamp(60px,min(21vh,12.5vw),200px);aspect-ratio:3/4;height:auto;object-fit:cover;object-position:50% 20%;border:2px solid #1b1a18;border-radius:3px}\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feat span{font:700 clamp(16px,2.8vh,22px)/1.05 var(--lz-font-display)!important;letter-spacing:.06em;color:#1b1a18;background:none!important;padding:0!important}\n.sk-stage:has(.sk-hud[data-wide=\"1\"]) .sk-buy .lz-feat small{font:700 clamp(16px,2.8vh,20px)/1 var(--lz-font-display)!important;color:#f2ead8!important;background:var(--red,#c8372d)!important;border-radius:999px;padding:.18em .7em!important}\n}\n/* the ink switch at the smallest heights: never under 12px */\n@media (max-height:330px){ .sk-ink button b{font-size:13px} }\n/* the buy confirmation at the smallest heights (400x225): no picture, a smaller start stamp, so the whole sheet fits */\n@media (max-height:330px){ #lzBuy .lz-sheet::before{display:none} #lzBuy #lzBuyYes{width:60px;height:60px;font-size:15px} #lzBuy .lz-sheet{padding-top:8px;padding-bottom:8px} }\n/* standard 1.11 (8.2): during a round the bar looks exactly as it does when ready. Nothing disappears, dims or changes\n   shape, on a phone too and under a celebration: no stop square, no turning enso, the label stays PLAY. The core\n   keeps +/-, TURBO, AUTO, the ink switch and the buy stamps disabled mid-round, so a press on them simply does nothing. */\n#lzApp.sk-bar :is(#lzMinus,#lzPlus,#lzFast,#lzAuto):disabled{opacity:1!important;visibility:visible!important}\n#lzApp.sk-bar .lz-stepper:has(#lzAction.busy) :is(#lzMinus,#lzPlus){opacity:1!important;visibility:visible!important;pointer-events:none}\n#lzApp:has(#lzAction.busy) .sk-buy,.sk-stage:has(~ .lz-panel #lzAction.busy) .sk-buy{opacity:1!important;pointer-events:none}\n.sk-buy .lz-feat:disabled{opacity:1!important}\n#lzApp:has(#lzAction.busy) .sk-ink{opacity:1!important}\n#lzApp.sk-bar #lzAction.busy .sk-enso{opacity:1!important;transform:none!important;animation:none!important}\n#lzApp.sk-bar #lzAction.busy .sk-stop{opacity:0!important}\n#lzApp.sk-bar #lzAction.busy span{opacity:1!important}\n#lzApp.sk-bar #lzAction:disabled:not(.busy){opacity:1!important}\n/* the drops count always reads over the sleeping dragon (on a short phone the board sits lower and the dragon reached it) */\n.sk-drops{z-index:2}\n";
